async () => {
  const cards=[...document.querySelectorAll('#grid .sb-card')];
  const first=cards[0].getAttribute('href');
  // follow the first card like a click, then report
  const res=await fetch(first).then(r=>r.status);
  const imgs=[...document.querySelectorAll('#grid img')];
  return {cards:cards.length, first, firstStatus:res, broken:imgs.filter(i=>i.complete&&i.naturalWidth===0).length,
    featured:document.querySelectorAll('.sb-badge.feat').length, early:document.querySelectorAll('.sb-badge.ea').length,
    caps:document.querySelectorAll('.sb-badge.cap').length};
}
